namespace Onyx.Application.Search;

/// <summary>
/// One searchable page in one language, built only from the live, public snapshot. Display fields keep the original text; the
/// normalized fields feed the full-text vectors and trigram index (generated by the database).
/// </summary>
public sealed record SearchDocumentData(
    Guid ContentItemId,
    string LanguageCode,
    string ContentType,
    string Group,
    string Title,
    string Summary,
    string Path,
    DateTimeOffset? PublishedAtUtc,
    Guid LiveRevisionId,
    string TitleNormalized,
    string SummaryNormalized,
    string BodyNormalized,
    string NamesNormalized);
